Clase Caja
    Publico Definir contenido Como Entero;
FinClase

Proceso CompararTrasCopiar
    Definir bandera Como Entero;
    Definir original Como Caja;
    Definir otro Como Caja;
    Leer bandera;
    original <- Nuevo Caja();
    Si bandera = 1 Entonces
        otro <- Copiar(original);
    SiNo
        otro <- original;
    FinSi
    Si original = otro Entonces
        Escribir 1;
    SiNo
        Escribir 0;
    FinSi
FinProceso
